"SELECT DISTINCT\r\nSPI.[PROV_ID]                                   AS PROV_ID,\r\nSPI.[Submitting Provider Name] \t\t\t\t    AS \"PCP Name\",\r\nSPI.[Submitting Provider Type]\t\t            AS \"PCP Type\",\r\nSPI.[Submitting Provider NPI]\t\t\t        AS \"PCP NPI\",\r\nSPI.[Submitting Provider State License ID]\t\tAS \"PCP State License ID\",\r\nSPI.[Submitting Provider Medicaid ID]\t\t\tAS \"PCP Medicaid ID\",\r\n--SPI.[Submitting Provider Tax ID SSN]            AS \"PCP Tax ID SSN\",\r\nSPI.[Submitting Provider Network Access Vendor] AS \"PCP Network Access Vendor\"\r\nFROM [Submitting Provider Information] AS SPI\r\n"
